function validate([coordinates, k]) {
  if (!Array.isArray(coordinates) || coordinates.length < 1 || coordinates.length > 100000) return 'coordinates needs 1 to 10^5 points.';
  const seen = new Set();
  for (const point of coordinates) {
    if (!Array.isArray(point) || point.length !== 2) return 'Each point is a pair [x, y].';
    if (point.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'Each coordinate is an integer from 0 to 10^9.';
    const key = point[0] + ',' + point[1];
    if (seen.has(key)) return 'All points must be distinct.';
    seen.add(key);
  }
  if (!Number.isInteger(k) || k < 0 || k >= coordinates.length) return 'k must be a valid index into coordinates.';
  return null;
}

