function maxPathLength(coordinates, k) {
  const [kx, ky] = coordinates[k];

  const longestChain = (points) => {
    points.sort((a, b) => a[0] - b[0] || b[1] - a[1]);
    const tails = [];
    for (const [, y] of points) {
      let left = 0;
      let right = tails.length;
      while (left < right) {
        const mid = (left + right) >> 1;
        if (tails[mid] < y) {
          left = mid + 1;
        } else {
          right = mid;
        }
      }
      tails[left] = y;
    }
    return tails.length;
  };

  const before = coordinates.filter(([x, y]) => x < kx && y < ky);
  const after = coordinates.filter(([x, y]) => x > kx && y > ky);
  return longestChain(before) + 1 + longestChain(after);
}

