function maxPathLength(coordinates, k) {
  // Longest chain ending at a point plus longest chain starting there, by memoised search over all pairs.
  const n = coordinates.length;
  const smaller = (a, b) => a[0] < b[0] && a[1] < b[1];
  const ending = new Array(n).fill(0);
  const starting = new Array(n).fill(0);
  const endAt = (i) => {
    if (ending[i]) return ending[i];
    let best = 1;
    for (let j = 0; j < n; j++) if (smaller(coordinates[j], coordinates[i])) best = Math.max(best, endAt(j) + 1);
    return (ending[i] = best);
  };
  const startAt = (i) => {
    if (starting[i]) return starting[i];
    let best = 1;
    for (let j = 0; j < n; j++) if (smaller(coordinates[i], coordinates[j])) best = Math.max(best, startAt(j) + 1);
    return (starting[i] = best);
  };
  return endAt(k) + startAt(k) - 1;
}

