function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const points = [];
  const seen = new Set();
  const add = (x, y) => {
    const key = x + ',' + y;
    if (!seen.has(key)) { seen.add(key); points.push([x, y]); }
  };
  if (size === 'small') {
    // Small grids force equal x and equal y values; the points must stay distinct.
    const top = rand() < 0.8 ? int(1, 6) : 1000000000;
    const n = Math.min(int(1, 9), (top + 1) * (top + 1));
    while (points.length < n) add(int(0, top), int(0, top));
    return [points, int(0, n - 1)];
  }
  const n = int(1500, 2000);
  const shape = Math.floor(rand() * 3);
  while (points.length < n) {
    if (shape === 0) add(int(0, 1000000000), int(0, 1000000000));
    else if (shape === 1) {
      // Points near the diagonal form very long increasing paths.
      const t = int(0, 999000) * 1000;
      add(t + int(0, 50000), t + int(0, 50000));
    } else add(int(0, 60), int(0, 60));
  }
  return [points, int(0, n - 1)];
}
